export const projectsString = projects
  .map(
    ({
      name,
      repo_url,
      repo_url2,
      deployed_url,
      descriptionPoints,
      techStack,
    }) =>
      commonCardHtml({
        name,
        repo_url,
        repo_url2,
        deployed_url,
        descriptionPoints,
        techStack,
      }),
  )
  .join("<hr class='line'/>");

